import { clockOfSessionMinute } from '../time';
import type { EventOutcome, Expr, Outcome, Span, Win } from './ast';
import type { RawError } from './parser';
import { renderExpr } from './render';

export type Ty = 'price' | 'points' | 'count' | 'scalar' | 'weekday' | 'wdname' | 'bool' | 'error';

const TYPE_NAME: Record<Ty, string> = {
  price: 'price',
  points: 'points',
  count: 'count',
  scalar: 'number',
  weekday: 'weekday',
  wdname: 'weekday name',
  bool: 'condition',
  error: 'error',
};
export const typeName = (t: Ty): string => TYPE_NAME[t];
const numeric = (t: Ty): boolean => t === 'price' || t === 'points' || t === 'count' || t === 'scalar';

export class TypeChecker {
  readonly errors: RawError[] = [];

  private err(at: Span, message: string): 'error' {
    this.errors.push({ code: 'E_TYPE', offset: at.offset, length: Math.max(1, at.length), message });
    return 'error';
  }

  private arith(e: Extract<Expr, { t: 'bin' }>): Ty {
    let lt = this.infer(e.l);
    let rt = this.infer(e.r);
    if (lt === 'error' || rt === 'error') return 'error';
    const L = renderExpr(e.l), R = renderExpr(e.r), op = e.op;
    const head = `${L} ${op} ${R}: `;
    const generic = (): Ty => this.err(e.span, `${head}A ${typeName(lt)} and a ${typeName(rt)} cannot be combined with ${op}.`);
    if (!numeric(lt) || !numeric(rt)) return generic();
    if (op === '+' || op === '-') {
      if (lt === 'scalar' && rt === 'scalar') return 'scalar';
      if (lt === 'scalar') lt = rt === 'price' || rt === 'points' ? 'points' : 'count';
      if (rt === 'scalar') rt = lt === 'price' || lt === 'points' ? 'points' : 'count';
      if (op === '+') {
        if (lt === 'price' && rt === 'price') return this.err(e.span, `${head}Adding two prices has no meaning. For their midpoint use mid(a, b).`);
        if ((lt === 'price' && rt === 'points') || (lt === 'points' && rt === 'price')) return 'price';
        if (lt === 'points' && rt === 'points') return 'points';
        if (lt === 'count' && rt === 'count') return 'count';
        // a price or distance plus a count
        return this.err(e.span, `${head}Add a distance in points, not a count.`);
      }
      if (lt === 'price' && rt === 'points') return 'price';
      if (lt === 'price' && rt === 'price') return 'points';
      if (lt === 'points' && rt === 'points') return 'points';
      if (lt === 'count' && rt === 'count') return 'count';
      if (lt === 'points' && rt === 'price') return this.err(e.span, `${head}A distance minus a price has no meaning. Write price - distance.`);
      return generic();
    }
    if (lt === 'scalar' && rt === 'scalar') return 'scalar';
    if (lt === 'scalar') lt = 'count';
    if (rt === 'scalar') rt = 'count';
    if (op === '*') {
      if (lt === 'count' && rt === 'count') return 'count';
      if ((lt === 'price' && rt === 'count') || (lt === 'count' && rt === 'price')) return 'price';
      if ((lt === 'points' && rt === 'count') || (lt === 'count' && rt === 'points')) return 'points';
      return this.err(e.span, `${head}Multiplying two prices or distances has no meaning.`);
    }
    if (lt === 'price' && rt === 'count') return 'price';
    if (lt === 'points' && rt === 'count') return 'points';
    if (lt === rt) return 'count';
    return this.err(e.span, `${head}Divide a distance by a distance or a price by a price.`);
  }

  private cmpTypes(l: Expr, r: Expr, head: string, at: Span): Ty {
    let lt = this.infer(l);
    let rt = this.infer(r);
    if (lt === 'error' || rt === 'error') return 'error';
    if (lt === 'weekday' || rt === 'weekday' || lt === 'wdname' || rt === 'wdname')
      return this.err(at, `${head}A weekday is compared only as weekday = mon, weekday != mon, weekday in (...) or weekday not in (...).`);
    if (lt === 'scalar' && rt !== 'scalar') lt = rt;
    if (rt === 'scalar' && lt !== 'scalar') rt = lt;
    if (lt === 'scalar' && rt === 'scalar') return 'bool';
    if (lt === rt && numeric(lt)) return 'bool';
    return this.err(at, `${head}A ${typeName(lt)} cannot be compared with a ${typeName(rt)}.`);
  }

  private memo = new WeakMap<Expr, Ty>();

  /** The type of an expression; each node is checked (and reports its errors) once. */
  infer(e: Expr): Ty {
    const m = this.memo.get(e);
    if (m !== undefined) return m;
    const t = this.inferOnce(e);
    this.memo.set(e, t);
    return t;
  }

  private inferOnce(e: Expr): Ty {
    switch (e.t) {
      case 'num': {
        if (e.of) {
          const t = this.infer(e.of);
          if (t === 'error') return 'error';
          if (t !== 'price' && t !== 'scalar')
            return this.err(e.span, `${renderExpr(e)}: A percent of a value needs a price; ${renderExpr(e.of)} is a ${typeName(t)}.`);
          return 'points';
        }
        return e.unit === 'none' ? 'scalar' : 'points';
      }
      case 'win':
        return e.field === 'range' || e.field === 'body' ? 'points' : e.field === 'volume' ? 'count' : 'price';
      case 'gap':
      case 'adr':
      case 'atr':
        return 'points';
      case 'weekday':
        return 'weekday';
      case 'wdname':
        return 'wdname';
      case 'early_close':
      case 'event':
      case 'all':
        return 'bool';
      case 'days_since':
      case 'days_to':
        return 'count';
      case 'at':
        return 'price';
      case 'neg': {
        const t = this.infer(e.x);
        if (t === 'error') return 'error';
        if (t === 'price') return this.err(e.span, 'A negative price has no meaning.');
        if (t === 'points' || t === 'count' || t === 'scalar') return t;
        return this.err(e.span, `A ${typeName(t)} cannot be negated.`);
      }
      case 'bin':
        return this.arith(e);
      case 'fn': {
        const ts = e.args.map((a) => this.infer(a));
        if (ts.includes('error')) return 'error';
        if (e.fn === 'abs') {
          if (ts.length !== 1) return 'error';
          if (ts[0] === 'price') return this.err(e.span, 'Prices are already positive; abs applies to distances.');
          if (numeric(ts[0])) return ts[0];
          return this.err(e.span, `abs applies to distances, not a ${typeName(ts[0])}.`);
        }
        if (e.fn === 'mid') {
          if (ts.length !== 2) return 'error';
          const bad = ts.find((t) => t !== 'price' && t !== 'scalar');
          if (bad) return this.err(e.span, `mid takes two prices, not a ${typeName(bad)}.`);
          return 'price';
        }
        if (ts.length < 2) return 'error';
        const bad = ts.find((t) => !numeric(t));
        if (bad) return this.err(e.span, `${e.fn} takes prices, distances or counts, not a ${typeName(bad)}.`);
        const kinds = [...new Set(ts.filter((t) => t !== 'scalar'))];
        if (kinds.length > 1) return this.err(e.span, `${e.fn} needs arguments of one type, not a ${typeName(kinds[0])} and a ${typeName(kinds[1])}.`);
        return kinds.length ? kinds[0] : 'scalar';
      }
      case 'cmp': {
        const lt = this.infer(e.l);
        if (lt === 'weekday') {
          const rt = this.infer(e.r);
          if (rt === 'error') return 'error';
          if (rt === 'wdname' && (e.op === '=' || e.op === '!=')) return 'bool';
          return this.err(e.span, `${renderExpr(e.l)} ${e.op} ${renderExpr(e.r)}: A weekday is compared only as weekday = mon, weekday != mon, weekday in (...) or weekday not in (...).`);
        }
        return this.cmpTypes(e.l, e.r, `${renderExpr(e.l)} ${e.op} ${renderExpr(e.r)}: `, e.span);
      }
      case 'between': {
        const head = `${renderExpr(e.x)} between ${renderExpr(e.a)} and ${renderExpr(e.b)}: `;
        const a = this.cmpTypes(e.x, e.a, head, e.span);
        if (a === 'error') return 'error';
        const b = this.cmpTypes(e.x, e.b, head, e.span);
        return b === 'error' ? 'error' : 'bool';
      }
      case 'in': {
        const xt = this.infer(e.x);
        const lts = e.list.map((x) => this.infer(x));
        if (xt === 'error' || lts.includes('error')) return 'error';
        if (xt !== 'weekday' || lts.some((t) => t !== 'wdname')) return this.err(e.span, 'in lists weekdays: weekday in (mon, fri).');
        return 'bool';
      }
      case 'and':
      case 'or': {
        const lt = this.infer(e.l);
        const rt = this.infer(e.r);
        if (lt === 'error' || rt === 'error') return 'error';
        if (lt !== 'bool' || rt !== 'bool')
          return this.err(e.span, `${renderExpr(e.l)} ${e.t} ${renderExpr(e.r)}: and, or and not join conditions that are true or false.`);
        return 'bool';
      }
      case 'not': {
        const t = this.infer(e.x);
        if (t === 'error') return 'error';
        if (t !== 'bool') return this.err(e.span, `not ${renderExpr(e.x)}: and, or and not join conditions that are true or false.`);
        return 'bool';
      }
    }
  }

  /** A whole text that must be true or false. */
  requireBool(e: Expr, whole: Span, what: 'setup' | 'outcome'): void {
    const t = this.infer(e);
    if (t === 'error' || t === 'bool') return;
    this.err(whole, `A ${what} must be true or false; this is a ${typeName(t)}.`);
  }

  requirePrice(level: Expr, at: Span): void {
    const t = this.infer(level);
    if (t === 'error' || t === 'price' || t === 'scalar') return;
    this.err(at, `${renderExpr(level)} is a ${typeName(t)}; an event needs a price level.`);
  }
}

// ---- values and known-at times ---------------------------------------------

/** [start, end) of a window in session minutes, before any clipping. */
export function winBounds(w: Win): [number, number] {
  switch (w.k) {
    case 'rth':
      return [930, 1320];
    case 'overnight':
      return [0, 930];
    case 'session':
      return [0, 1380];
    case 'prior':
      return [0, 0];
    case 'or':
      return [930, 930 + w.n];
    case 'window':
      return [w.a, w.b];
    case 'bar':
      return [w.t, w.t + w.len];
  }
}

export interface ValueRef {
  canon: string;
  knownAt: number;
  span: Span;
  expr: Expr;
}

/** Every value a text reads, in reading order. A bare percent reads prior.close. */
export function collectValues(e: Expr, out: ValueRef[] = []): ValueRef[] {
  switch (e.t) {
    case 'num':
      if (e.unit === '%') {
        if (e.of) collectValues(e.of, out);
        else out.push({ canon: 'prior.close', knownAt: 0, span: e.span, expr: e });
      }
      break;
    case 'win': {
      const [a, b] = winBounds(e.win);
      out.push({ canon: renderExpr(e), knownAt: e.win.k === 'prior' ? 0 : e.field === 'open' ? a : b, span: e.span, expr: e });
      break;
    }
    case 'gap':
      out.push({ canon: 'gap', knownAt: 930, span: e.span, expr: e });
      break;
    case 'adr':
    case 'atr':
    case 'weekday':
    case 'early_close':
    case 'event':
    case 'days_since':
    case 'days_to':
      out.push({ canon: renderExpr(e), knownAt: 0, span: e.span, expr: e });
      break;
    case 'at':
      out.push({ canon: renderExpr(e), knownAt: e.time, span: e.span, expr: e });
      break;
    case 'wdname':
    case 'all':
      break;
    case 'neg':
    case 'not':
      collectValues(e.x, out);
      break;
    case 'bin':
    case 'cmp':
    case 'and':
    case 'or':
      collectValues(e.l, out);
      collectValues(e.r, out);
      break;
    case 'fn':
      e.args.forEach((a) => collectValues(a, out));
      break;
    case 'between':
      collectValues(e.x, out);
      collectValues(e.a, out);
      collectValues(e.b, out);
      break;
    case 'in':
      collectValues(e.x, out);
      e.list.forEach((a) => collectValues(a, out));
      break;
  }
  return out;
}

/** The latest-known value (first in text order on ties), or null. */
export function latest(values: ValueRef[]): ValueRef | null {
  let best: ValueRef | null = null;
  for (const v of values) if (!best || v.knownAt > best.knownAt) best = v;
  return best;
}

export interface OutcomeWindow {
  /** event: start and static end in session minutes; state: known-at */
  kind: 'event' | 'state';
  start: number;
  end: number;
  endKind: 'time' | 'close' | 'session_close' | 'within' | 'default';
  knownAt: number;
  barMinutes: number;
}

const clk = clockOfSessionMinute;

/** Static window checks. Pushes errors and returns the window (meaningful only without errors). */
export function outcomeWindow(o: Outcome, decision: number, setupLatest: ValueRef | null, errors: RawError[]): OutcomeWindow {
  if (o.form === 'state') {
    const vals = collectValues(o.expr);
    const known = vals.length ? Math.max(...vals.map((v) => v.knownAt)) : 0;
    if (vals.length === 0) errors.push({ code: 'E_TYPE', offset: o.span.offset, length: o.span.length, message: 'An outcome must read the market.' });
    else if (known < decision)
      errors.push({
        code: 'E_OUTCOME_BEFORE_SETUP',
        offset: o.span.offset,
        length: o.span.length,
        message: `The outcome is known at ${clk(known)}, before the setup is known at ${clk(decision)}, so it cannot be a consequence of it.`,
      });
    return { kind: 'state', start: known, end: known, endKind: 'default', knownAt: known, barMinutes: 1 };
  }
  const ev = o as EventOutcome;
  const levels = collectValues(ev.first.level);
  if (ev.second) collectValues(ev.second.level, levels);
  const levelLatest = latest(levels);
  const kLevel = levelLatest ? levelLatest.knownAt : 0;
  const K = Math.max(decision, kLevel);
  const closesEvent = [ev.first, ev.second].find((x) => x && (x.kind === 'closes_above' || x.kind === 'closes_below'));
  const barMinutes = closesEvent ? closesEvent.barSize : 1;
  let start: number;
  if (ev.from) {
    start = ev.from.time!;
    if (start < K) {
      const setupCulprit = decision >= kLevel;
      const known = clk(K);
      const message = setupCulprit
        ? `The outcome window starts at ${clk(start)}, but the setup is only known at ${known} (${setupLatest ? setupLatest.canon : 'the setup'}). Start the window at ${known} or later.`
        : `The outcome window starts at ${clk(start)}, but ${levelLatest!.canon} is only known at ${known}. Start the window at ${known} or later.`;
      errors.push({ code: 'E_LOOKAHEAD', offset: ev.from.span.offset, length: ev.from.span.length, message });
      return { kind: 'event', start, end: 1320, endKind: 'default', knownAt: K, barMinutes };
    }
  } else start = Math.max(930, K);
  let end: number;
  let endKind: OutcomeWindow['endKind'];
  const c = ev.end;
  if (!c) {
    end = 1320;
    endKind = 'default';
  } else if (c.kind === 'within') {
    end = start + c.minutes!;
    endKind = 'within';
  } else if (c.end === 'close') {
    end = 1320;
    endKind = 'close';
  } else if (c.end === 'session_close') {
    end = 1380;
    endKind = 'session_close';
  } else {
    end = c.time!;
    endKind = 'time';
  }
  if (end <= start) {
    // the level is the culprit only when its known-at is what the window cannot reach
    // (a level known before the session opens never is: `by 18:00` is an empty window)
    if (levelLatest && kLevel > 0 && kLevel >= end) {
      errors.push({
        code: 'E_LOOKAHEAD',
        offset: levelLatest.span.offset,
        length: levelLatest.span.length,
        message: `${levelLatest.canon} is only known at ${clk(kLevel)}, when the outcome window has already ended.`,
      });
    } else {
      const at = c ? c.span : { offset: o.span.offset, length: firstTokenLength(ev) };
      errors.push({ code: 'E_EMPTY_WINDOW', offset: at.offset, length: at.length, message: `The outcome window is empty: it starts at ${clk(start)} and ends at ${clk(end)}.` });
    }
  }
  return { kind: 'event', start, end, endKind, knownAt: K, barMinutes };
}

function firstTokenLength(ev: EventOutcome): number {
  return ev.neg ? 3 : ev.first.kind === 'touches' ? 7 : 6;
}
